package org.khtml

data class SourcePosition(
    val line: Int,
    val col: Int
)

sealed interface HtmlToken {
    val position: SourcePosition

    data class TagOpen(
        val name: String,
        val attributes: Map<String, String> = emptyMap(),
        override val position: SourcePosition
    ) : HtmlToken

    data class TagClose(
        val name: String,
        override val position: SourcePosition
    ) : HtmlToken

    data class Text(
        val content: String,
        override val position: SourcePosition
    ) : HtmlToken
}

fun interface TokenizerRule {
    fun tryConsume(
        input: CharSequence,
        cursor: Int,
        out: MutableList<HtmlToken>
    ): Int
}

/**
 * Checks if '<' at [index] is a real tag that terminates with '>'.
 * If '<' never closes before EOF, it is not a tag start.
 */
fun isTagStart(input: CharSequence, index: Int): Boolean {
    if (input[index] != '<') return false

    val nextIndex = index + 1
    if (nextIndex >= input.length) return false

    val nextChar = input[nextIndex]
    val isValidStart = nextChar.isLetter() || nextChar == '/' || nextChar == '!'
    if (!isValidStart) return false

    // Lookahead: ensure there is a closing '>' somewhere ahead
    var end = nextIndex
    while (end < input.length && input[end] != '>') {
        end++
    }
    return end < input.length
}

object TagOpenRule : TokenizerRule {
    override fun tryConsume(
        input: CharSequence,
        cursor: Int,
        out: MutableList<HtmlToken>
    ): Int {
        if (!isTagStart(input, cursor)) return 0
        if (input[cursor + 1] == '/' || input[cursor + 1] == '!') return 0

        var end = cursor + 1
        while (end < input.length && input[end] != '>') {
            end++
        }

        val tagContent = input.subSequence(cursor + 1, end).toString().trim()
        val tagName = tagContent.takeWhile { !it.isWhitespace() && it != '/' }.lowercase()

        val attributes = mutableMapOf<String, String>()
        val attrString = tagContent.substring(tagName.length).trim()
        if (attrString.isNotEmpty()) {
            parseAttributes(attrString, attributes)
        }

        out.add(
            HtmlToken.TagOpen(
                name = tagName,
                attributes = attributes,
                position = SourcePosition(line = 1, col = cursor + 2)
            )
        )

        return (end + 1) - cursor
    }

    private fun parseAttributes(rawAttrs: String, out: MutableMap<String, String>) {
        var i = 0
        while (i < rawAttrs.length) {
            while (i < rawAttrs.length && (rawAttrs[i].isWhitespace() || rawAttrs[i] == '/')) {
                i++
            }
            if (i >= rawAttrs.length) break

            val keyStart = i
            while (i < rawAttrs.length && rawAttrs[i] != '=' && !rawAttrs[i].isWhitespace() && rawAttrs[i] != '/') {
                i++
            }
            val key = rawAttrs.substring(keyStart, i).lowercase()

            while (i < rawAttrs.length && rawAttrs[i].isWhitespace()) {
                i++
            }

            if (i < rawAttrs.length && rawAttrs[i] == '=') {
                i++
                while (i < rawAttrs.length && rawAttrs[i].isWhitespace()) {
                    i++
                }
                if (i < rawAttrs.length) {
                    val quote = rawAttrs[i]
                    if (quote == '"' || quote == '\'') {
                        i++
                        val valStart = i
                        while (i < rawAttrs.length && rawAttrs[i] != quote) {
                            i++
                        }
                        val value = rawAttrs.substring(valStart, i)
                        if (i < rawAttrs.length && rawAttrs[i] == quote) {
                            i++
                        }
                        out[key] = value
                    } else {
                        val valStart = i
                        while (i < rawAttrs.length && !rawAttrs[i].isWhitespace() && rawAttrs[i] != '>') {
                            i++
                        }
                        out[key] = rawAttrs.substring(valStart, i)
                    }
                }
            } else {
                out[key] = ""
            }
        }
    }
}

object TagCloseRule : TokenizerRule {
    override fun tryConsume(
        input: CharSequence,
        cursor: Int,
        out: MutableList<HtmlToken>
    ): Int {
        if (!isTagStart(input, cursor)) return 0
        if (cursor + 1 >= input.length || input[cursor + 1] != '/') return 0

        var end = cursor + 2
        while (end < input.length && input[end] != '>') {
            end++
        }

        val tagName = input.subSequence(cursor + 2, end).toString().trim().lowercase()
        out.add(
            HtmlToken.TagClose(
                name = tagName,
                position = SourcePosition(line = 1, col = cursor + 2)
            )
        )

        return (end + 1) - cursor
    }
}

object TextRule : TokenizerRule {
    override fun tryConsume(
        input: CharSequence,
        cursor: Int,
        out: MutableList<HtmlToken>
    ): Int {
        if (isTagStart(input, cursor)) return 0

        var end = cursor
        while (end < input.length) {
            if (isTagStart(input, end)) break
            end++
        }

        val text = input.subSequence(cursor, end).toString()

        out.add(
            HtmlToken.Text(
                content = text,
                position = SourcePosition(line = 1, col = cursor + 1)
            )
        )
        return end - cursor
    }
}

class Tokenizer(
    private val rules: List<TokenizerRule> = DEFAULT_RULES
) {
    fun tokenize(htmlSequence: CharSequence): List<HtmlToken> {
        if (htmlSequence.isEmpty()) return emptyList()

        val tokenBuf = mutableListOf<HtmlToken>()
        var cursor = 0

        while (cursor < htmlSequence.length) {
            var matched = false

            for (rule in rules) {
                val consumed = rule.tryConsume(htmlSequence, cursor, tokenBuf)
                if (consumed > 0) {
                    cursor += consumed
                    matched = true
                    break
                }
            }

            if (!matched) {
                cursor++
            }
        }

        return tokenBuf
    }

    companion object {
        val DEFAULT_RULES: List<TokenizerRule> = listOf(
            TagCloseRule,
            TagOpenRule,
            TextRule
        )
    }
}
